:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #102a2a;
  color: #183838;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #24514b 0, #102a2a 68%);
}

.card {
  width: min(100%, 520px);
  padding: clamp(22px, 6vw, 38px);
  border: 1px solid #d6e6d8;
  border-radius: 24px;
  background: #f5f3e9;
  box-shadow: 0 24px 70px #06161580;
}

.header { margin-bottom: 28px; }
.eyebrow { margin: 0 0 7px; color: #b45e3e; font-size: .82rem; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; color: #183838; font-size: clamp(1.8rem, 8vw, 2.35rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 12px 0 0; color: #52706a; line-height: 1.5; }

.board { width: min(100%, 390px); margin: 0 auto; }
.grid-wrap { display: grid; grid-template-columns: minmax(0, 1fr) 70px; gap: 8px; }
.grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; }
.cell {
  width: 100%; min-width: 0; aspect-ratio: 1;
  border: 1px solid #c5d9ce; border-radius: 12px;
  background: #e2eee5; color: #183838;
  font: inherit; font-size: clamp(1rem, 5vw, 1.25rem); font-weight: 700; text-align: center;
  outline: none; transition: background .15s, border-color .15s, box-shadow .15s;
}
.cell:hover { border-color: #5f9580; background: #d6e9dd; }
.cell:focus { border-color: #b45e3e; box-shadow: 0 0 0 3px #b45e3e55; }
.row-sums { display: grid; grid-template-rows: repeat(4, 1fr); gap: 7px; }
.sum, .column-sum { display: grid; place-items: center; border-radius: 12px; background: #e8e6da; color: #52706a; font-weight: 700; }
.sum { min-height: 44px; transition: background .15s, color .15s; }
.sum.is-largest { background: #b45e3e; color: white; }
.column-sums { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin: 8px 78px 0 0; }
.column-sum { min-height: 38px; font-size: .9rem; }
.total-row { display: flex; justify-content: space-between; align-items: center; margin-top: 28px; padding: 16px 0; border-top: 1px solid #d6dfd4; color: #52706a; }
.total-row strong { color: #183838; font-size: 1.5rem; font-variant-numeric: tabular-nums; }
.randomize {
  width: 100%; min-height: 52px; border: 0; border-radius: 13px;
  background: #183f3b; color: #fff; cursor: pointer;
  font: inherit; font-weight: 750; transition: background .15s, transform .1s, box-shadow .15s;
}
.randomize:hover { background: #245b50; }
.randomize:focus-visible { outline: 3px solid #b45e3e; outline-offset: 3px; }
.randomize:active { transform: translateY(1px); background: #102a2a; }
.randomize span { margin-left: 6px; font-size: 1.2rem; }
.hint { margin: 15px 0 0; color: #71847a; font-size: .88rem; line-height: 1.45; text-align: center; }

@media (max-width: 400px) {
  body { padding: 16px 10px; }
  .card { padding: 22px 18px; border-radius: 20px; }
  .grid-wrap { grid-template-columns: minmax(0, 1fr) 58px; gap: 6px; }
  .grid, .row-sums, .column-sums { gap: 5px; }
  .column-sums { margin-right: 64px; }
  .sum { min-height: 40px; }
}

const grid = document.querySelector('#number-grid');
const rowSums = document.querySelector('#row-sums');
const columnSums = document.querySelector('#column-sums');
const grandTotal = document.querySelector('#grand-total');
const cells = [];
const rowDisplays = [];
const columnDisplays = [];

for (let row = 0; row < 4; row += 1) {
  for (let column = 0; column < 4; column += 1) {
    const input = document.createElement('input');
    input.className = 'cell';
    input.type = 'number';
    input.min = '0';
    input.step = '1';
    input.value = '0';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${column + 1}`);
    input.addEventListener('input', updateSums);
    grid.append(input);
    cells.push(input);
  }

  const sum = document.createElement('div');
  sum.className = 'sum';
  sum.setAttribute('aria-label', `Row ${row + 1} sum`);
  rowSums.append(sum);
  rowDisplays.push(sum);
}

for (let column = 0; column < 4; column += 1) {
  const sum = document.createElement('div');
  sum.className = 'column-sum';
  sum.setAttribute('aria-label', `Column ${column + 1} sum`);
  columnSums.append(sum);
  columnDisplays.push(sum);
}

function updateSums() {
  const values = cells.map((cell) => Math.max(0, Number.parseInt(cell.value, 10) || 0));
  const rows = [0, 1, 2, 3].map((row) => values.slice(row * 4, row * 4 + 4).reduce((sum, value) => sum + value, 0));
  const columns = [0, 1, 2, 3].map((column) => values.reduce((sum, value, index) => sum + (index % 4 === column ? value : 0), 0));
  const largest = Math.max(...rows);

  rowDisplays.forEach((display, index) => {
    display.textContent = rows[index];
    display.classList.toggle('is-largest', rows[index] === largest);
  });
  columnDisplays.forEach((display, index) => { display.textContent = columns[index]; });
  grandTotal.textContent = values.reduce((sum, value) => sum + value, 0);
}

document.querySelector('#randomize').addEventListener('click', () => {
  cells.forEach((cell) => { cell.value = Math.floor(Math.random() * 9) + 1; });
  updateSums();
});

updateSums();
